#pragma once
//==============================================================================
// Sobol' quasi-random sampler with Owen scrambling
//
// Produces a (0,2)-sequence in each pair of dimensions, giving O((log N)^d / N)
// convergence vs O(1/sqrt(N)) for pure Monte Carlo.
//
// Design:
//   - Pure device header — include from both cuda_utils.cuh and optix_programs.cu
//   - Direction vectors from Joe-Kuo 2010, hosted in 16 KB of __constant__ memory
//   - Owen scrambling via Laine-Karras hash (no texture, no host memory)
//   - Gray-code sample ordering for better progressive convergence
//   - SOBOL_MAX_DIM dimensions; overflow falls back to PCG silently
//
// Usage (CUDA path via curandState* cast):
//   See cuda_utils.cuh — rand_float() branches on g_use_sobol automatically.
//
// Usage (OptiX path via PRDRadiance fields):
//   See optix_programs.cu — sobol_rand_float_optix() reads/increments
//   prd->sobol_dim_idx and passes pixel_hash from params.
//
// References:
//   Joe & Kuo, "Constructing Sobol Sequences with Better Two-Dimensional Projections"
//     SIAM J. Sci. Comput. 30 (2008) 2635-2654.
//   Laine & Karras, "Stratified Sampling for Stochastic Transparency" (Eurographics 2011)
//   Burley, "Practical Hash-based Owen Scrambling" JCGT vol. 9 (2020)
//==============================================================================

#ifdef __CUDACC__

#include <cstdint>

//------------------------------------------------------------------------------
// Direction vectors — 128 dimensions × 32 bits
// Generated from the Joe-Kuo table (s,a,m) via the standard initialisation
// recurrence. Dimension 0 is the van der Corput sequence (base 2).
// 128 dims × 32 uint32 = 16 384 bytes — well within CUDA's 64 KB constant limit.
//------------------------------------------------------------------------------
