//------------------------------------------------------------------------------
// Constants
//------------------------------------------------------------------------------
constexpr int SOBOL_MAX_DIM = 128;

//------------------------------------------------------------------------------
// Gray-code index — converts sample index n to the Gray code.
// Used so that consecutive sample indices flip only one bit in the direction
// vectors, giving better progressive convergence.
//   g(0)=0, g(1)=1, g(2)=3, g(3)=2, g(4)=6, ...
//------------------------------------------------------------------------------
__device__ __forceinline__ uint32_t sobol_gray(uint32_t n)
{
   return n ^ (n >> 1u);
}

//------------------------------------------------------------------------------
// Evaluate one Sobol' coordinate.
// index : sample index (use sobol_gray(n) for progressive ordering)
// dim   : dimension in [0, SOBOL_MAX_DIM)
// Returns a raw uint32 in [0, 2^32).
//------------------------------------------------------------------------------
__device__ __forceinline__ uint32_t sobol_uint(uint32_t index, int dim)
{
   uint32_t result = 0u;
   // XOR direction vectors for each set bit in index
   for (int bit = 0; bit < 32 && index != 0u; ++bit, index >>= 1u)
   {
      if (index & 1u)
         result ^= sobol_directions[dim][bit];
   }
   return result;
}

//------------------------------------------------------------------------------
// Laine-Karras hash — maps uint→uint bijection, used as nested scramble.
// Burley 2020 recommends this specific hash for Owen scrambling fidelity.
//------------------------------------------------------------------------------
__device__ __forceinline__ uint32_t laine_karras_hash(uint32_t x, uint32_t seed)
{
   x += seed;
   x ^= x * 0x6c62272eu;
   x += 0x285b7337u;
   x ^= x * 0x6c62272eu;
   x += 0xb9a25826u;
   x ^= x * 0x6c62272eu;
   return x;
}

//------------------------------------------------------------------------------
// Bit-reversal of a 32-bit integer.
//------------------------------------------------------------------------------
__device__ __forceinline__ uint32_t reverse_bits32(uint32_t x)
{
   x = ((x & 0xaaaaaaaa) >> 1) | ((x & 0x55555555) << 1);
   x = ((x & 0xcccccccc) >> 2) | ((x & 0x33333333) << 2);
   x = ((x & 0xf0f0f0f0) >> 4) | ((x & 0x0f0f0f0f) << 4);
   x = ((x & 0xff00ff00) >> 8) | ((x & 0x00ff00ff) << 8);
   return (x >> 16) | (x << 16);
}

//------------------------------------------------------------------------------
// Owen scrambling.
// x    : raw Sobol uint to scramble
// seed : per-dimension-per-pixel scramble seed
//
// Implements nested uniform scrambling: hash each prefix of x independently,
// using the Burley/Laine-Karras approach.  Preserves the (t,s,d)-net property.
//------------------------------------------------------------------------------
__device__ __forceinline__ uint32_t owen_scramble(uint32_t x, uint32_t seed)
{
   x = reverse_bits32(x);
   x ^= x * 0x3d20adeau;
   x += seed;
   x *= (seed >> 16) | 1u;
   x ^= x * 0x05526c56u;
   x ^= x * 0x53a22864u;
   return reverse_bits32(x);
}

//------------------------------------------------------------------------------
// Per-dimension scramble seed derived from the pixel hash.
// Different dimensions get different seeds to avoid correlated strata.
//------------------------------------------------------------------------------
__device__ __forceinline__ uint32_t dim_seed(uint32_t pixel_hash, int dim)
{
   // Mix pixel hash with dim index using a small hash to produce independent seeds.
   uint32_t h = pixel_hash ^ (uint32_t)(dim * 0x9e3779b9u);
   h ^= h >> 16;
   h *= 0x45d9f3bu;
   h ^= h >> 16;
   return h;
}

//------------------------------------------------------------------------------
// Full scrambled Sobol' float in [0, 1).
// sample_idx : absolute sample index (caller passes sobol_gray(n) for progressive)
// dim        : which dimension
// pixel_hash : stable per-pixel hash (from pixel coords + scene seed)
//------------------------------------------------------------------------------
__device__ __forceinline__ float sobol_float(uint32_t sample_idx, int dim, uint32_t pixel_hash)
{
   uint32_t raw = sobol_uint(sample_idx, dim);
   uint32_t scrambled = owen_scramble(raw, dim_seed(pixel_hash, dim));
   // Map to [0, 1): multiply by 2^-32
   return (float)(scrambled >> 8) * (1.0f / 16777216.0f);
}

//------------------------------------------------------------------------------
// PCG fallback for dimensions beyond SOBOL_MAX_DIM.
// Modifies the seed in-place identically to the CUDA renderer's rand_float.
//------------------------------------------------------------------------------
__device__ __forceinline__ float pcg_rand_float(uint32_t &seed)
{
   seed = seed * 747796405u + 2891336453u;
   uint32_t word = ((seed >> ((seed >> 28u) + 4u)) ^ seed) * 277803737u;
   uint32_t result = (word >> 22u) ^ word;
   return result * (1.0f / 4294967296.0f);
}

//------------------------------------------------------------------------------
// MurmurHash3 fmix32 — full avalanche finalizer.
// Every output bit depends on every input bit; required for independent per-use seeds.
//------------------------------------------------------------------------------
__device__ __forceinline__ uint32_t fmix32(uint32_t h)
{
   h ^= h >> 16;
   h *= 0x85ebca6bu;
   h ^= h >> 13;
   h *= 0xc2b2ae35u;
   h ^= h >> 16;
   return h;
}

//------------------------------------------------------------------------------
// Owen-scrambled 2D (0,2)-sequence Sobol sample.
//
// This is the approach from "Stratified Sampling for Stochastic Transparency"
// (Laine & Karras) and the ShaderToy reference implementation:
//
//   1. Derive independent per-use seeds from (pixel_hash, bounce, effect)
//   2. Shuffle the sample index per-pixel — different pixels explore different
//      permutations of the same Sobol sequence (cross-pixel decorrelation)
//   3. Look up dims 0 & 1 of the Joe-Kuo (0,2) table at the shuffled index
//   4. Owen-scramble each component independently
//
// Result: adjacent pixels get completely independent 2D Sobol samples even at
// 1 spp, and each (bounce, effect) pair gets its own decorrelated sequence.
//------------------------------------------------------------------------------
__device__ __forceinline__ float2 sobol_2d_sample(uint32_t sample_n, uint32_t bounce, uint32_t effect,
                                                   uint32_t pixel_hash)
{
   // Master seed: unique per (pixel, bounce, effect)
   uint32_t seed = fmix32(pixel_hash ^ (bounce * 0x9e3779b9u));
   seed          = fmix32(seed       ^ (effect * 0x517cc1b7u));

   uint32_t shuffle_seed = fmix32(seed ^ 0u);  // index permutation
   uint32_t x_seed       = fmix32(seed ^ 1u);  // x value scramble
   uint32_t y_seed       = fmix32(seed ^ 2u);  // y value scramble

   // Shuffle the sample index: owen_scramble is a bijection preserving the
   // (0,2)-net stratification property, giving per-pixel sequence permutations.
   uint32_t shuffled_n = owen_scramble(sobol_gray(sample_n), shuffle_seed);

   // 2D Sobol point from the canonical best-projecting pair (dims 0 and 1)
   uint32_t x_raw = sobol_uint(shuffled_n, 0);
   uint32_t y_raw = sobol_uint(shuffled_n, 1);

   // Owen-scramble each component with its own seed
   x_raw = owen_scramble(x_raw, x_seed);
   y_raw = owen_scramble(y_raw, y_seed);

   constexpr float scale = 1.0f / 4294967296.0f;
   return {x_raw * scale, y_raw * scale};
}

